def is_bored(S):
    sentences = []
    current_sentence = []

    for char in S:
        if char in '.!?':
            if current_sentence:
                sentences.append(''.join(current_sentence).strip())
                current_sentence = []
        else:
            current_sentence.append(char)

    if current_sentence:
        sentences.append(''.join(current_sentence).strip())

    count = sum(1 for sentence in sentences if sentence.lower().startswith('i '))
    return count

